   Q('note', 'Wedgwood displayed his products in London __________', 'showrooms', 'He also opened elegant showrooms in London', 'He opened showrooms.', max=1),
   Q('note', 'Wedgwood\'s illustrated __________ allowed customers to order by post', 'catalogues', 'he produced illustrated catalogues', 'Catalogues allowed postal orders.', max=1),
